<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Pterodactyl\Models\Server; use Illuminate\Http\JsonResponse; use Illuminate\Validation\Rule; use Pterodactyl\Facades\Activity; use Pterodactyl\Jobs\Dezerx\InstallModpack; use Illuminate\Http\Client\ConnectionException; use Pterodactyl\Services\Dezerx\Catalogue\ModpackCatalogue; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\AddonRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\ModpackInstallRequest; class ModpackController extends ClientApiController { public function __construct(private readonly ModpackCatalogue $catalogue) { parent::__construct(); } public function index(AddonRequest $request, Server $server): JsonResponse { return new JsonResponse(['sources' => $this->catalogue->sources()]); } public function search(AddonRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'source' => ['required', 'string', Rule::in($this->catalogue->sources())], 'query' => ['present', 'nullable', 'string', 'max:120'], 'page' => ['nullable', 'integer', 'min:1', 'max:' . ModpackCatalogue::MAX_PAGE], ]); try { $payload = $this->catalogue->search( (string) $data['source'], trim((string) ($data['query'] ?? '')), (int) ($data['page'] ?? 1), ); } catch (ConnectionException) { return $this->unreachable(); } return new JsonResponse($payload + ['maxPage' => ModpackCatalogue::MAX_PAGE]); } public function versions(AddonRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'source' => ['required', 'string', Rule::in($this->catalogue->sources())], 'id' => ['required', 'string', 'max:120'], ]); try { $versions = $this->catalogue->versions((string) $data['source'], (string) $data['id']); } catch (ConnectionException) { return $this->unreachable(); } return new JsonResponse(['versions' => $versions]); } public function install(ModpackInstallRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'source' => ['required', 'string', Rule::in($this->catalogue->sources())], 'id' => ['required', 'string', 'max:120'], 'versionId' => ['nullable', 'string', 'max:120'], 'wipe' => ['nullable', 'boolean'], ]); try { $resolved = $this->catalogue->download( (string) $data['source'], (string) $data['id'], (string) ($data['versionId'] ?? ''), ); } catch (ConnectionException) { return $this->unreachable(); } if ($resolved === null) { return new JsonResponse([ 'errors' => [['code' => 'NoServerPack', 'detail' => 'That pack does not publish a server download. Install it from its own page instead.']], ], 422); } [$url, $filename, $kind] = $resolved; $minecraft = (string) $resolved[4]; $filename = basename($filename); $wipe = (bool) ($data['wipe'] ?? false); $running = InstallModpack::status($server->uuid)['state'] ?? 'idle'; if (in_array($running, ['stopping', 'downloading', 'installing'], true)) { return new JsonResponse([ 'errors' => [['code' => 'AlreadyRunning', 'detail' => 'A pack is already being installed on this server.']], ], 409); } InstallModpack::mark($server->uuid, 'stopping', 'Stopping the server.'); InstallModpack::dispatch( server: $server, url: $url, filename: $filename, kind: $kind, unpack: $kind === ModpackCatalogue::KIND_SERVER_ZIP, wipe: $wipe, minecraft: $minecraft, ); Activity::event('server:modpack.install') ->property(['source' => $data['source'], 'file' => $filename, 'kind' => $kind, 'wipe' => $wipe]) ->log(); return new JsonResponse([ 'queued' => true, 'file' => $filename, 'kind' => $kind, 'message' => match ($kind) { ModpackCatalogue::KIND_NONE => "Downloading {$filename} to the server root. It needs an egg that can resolve a modpack manifest.", default => $wipe ? "Wiping the server, then installing {$filename} and setting the startup command. This takes a few minutes for a large pack." : "Installing {$filename} and setting the startup command. This takes a few minutes for a large pack.", }, ], 202); } public function status(AddonRequest $request, Server $server): JsonResponse { return new JsonResponse(InstallModpack::status($server->uuid)); } private function unreachable(): JsonResponse { return new JsonResponse([ 'errors' => [['code' => 'CatalogueUnreachable', 'detail' => 'That catalogue could not be reached. Try again shortly.']], ], 504); } } 